type SnakeComponent<Props = Record<string, unknown>, Emits extends object = {}> = DefineComponent<
    Props,
    {},
    {},
    {},
    {},
    {},
    {},
    { [Name in keyof Emits]: Emits[Name] extends unknown[] ? (...args: Emits[Name]) => void : never }
>;

